/// Decode an instruction in the 'inst16a' slot. Returns None on undefined.
pub fn decode_inst16a(insn: u32) -> Option<Opcode> {
    if fld_inst16a::op0(insn) == 8 {
        return Some(Opcode::OPCODE_L32I_N);
    }
    if fld_inst16a::op0(insn) == 9 {
        return Some(Opcode::OPCODE_S32I_N);
    }
    if fld_inst16a::op0(insn) == 10 {
        return Some(Opcode::OPCODE_ADD_N);
    }
    if fld_inst16a::op0(insn) == 11 {
        return Some(Opcode::OPCODE_ADDI_N);
    }
    return None;
}

